#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve() {
    ll n;
    cin >> n;

    string s;
    cin >> s;

    vector<ll> ans;
    ll i = 0;

    while (i < n && s[i] == '0') {
        ans.push_back(0);
        ++i;
    }

    while (i < n) {
        if (s[i] == '0') {
            ans.push_back(0);
            ++i;
        } else {
            ll j = i;
            while (j < n && s[j] == '1') {
                ++j;
            }

            ans.push_back(j - i);
            i = (j < n ? j + 1 : j);
        }
    }

    for (ll value : ans) {
        cout << value;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

